+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement in those days,
+ * and difference = actual - theoretical. Items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const round3 = (n) => Math.round(n * 1000) / 1000;
+  const byItem = new Map();
+  const line = (itemId) => {
+    if (!byItem.has(itemId)) byItem.set(itemId, { theoretical: 0, actual: 0 });
+    return byItem.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const u of s.uses) line(u.itemId).theoretical += u.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || m.qty <= 0) continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (!batch) continue;
+    line(batch.itemId).actual += m.qty;
+  }
+  return [...byItem]
+    .map(([itemId, l]) => {
+      const theoretical = round3(l.theoretical);
+      const actual = round3(l.actual);
+      return { itemId, theoretical, actual, difference: round3(actual - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
