+// Sales from the till. Each dish sold uses one portion of its recipe per
+// unit of `qty`; the ingredients are consumed with ref `sale:<ticket>`. A
+// ticket is imported once. Recording is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function hasTicket(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines [{ ticket, soldAt, dishId, qty, row }] and consumes their
+ * ingredients. Lines of tickets already imported are skipped. Checks every
+ * line before changing anything; throws sale_not_enough_stock naming the row.
+ * Returns { tickets, dishes } for what was recorded.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !hasTicket(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = getDish(store, l.dishId);
+    const uses = scaled(getRecipe(store, dish.recipeId), l.qty).filter((u) => u.qty > 0);
+    return { ...l, uses };
+  });
+  const used = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      const item = getItem(store, u.itemId);
+      const before = used.get(u.itemId) ?? 0;
+      const available = round3(onHand(store, u.itemId) - before);
+      if (available < u.qty)
+        throw new AppError("sale_not_enough_stock", { row: p.row, item: item.name, available, unit: item.unit });
+      used.set(u.itemId, round3(before + u.qty));
+    }
+  }
+  store.data.sales ??= [];
+  const tickets = new Set();
+  let dishes = 0;
+  for (const p of planned) {
+    for (const u of p.uses) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    tickets.add(p.ticket);
+    dishes += p.qty;
+  }
+  return { tickets: tickets.size, dishes };
+}
